/**
 * Upplýsingar um hvern flokk í „Svif foreldrar“ (engin persónugögn, bara flokkarnir sjálfir).
 * Lykillinn er flokkanúmerið, t.d. „G7-09“, eins og það stendur fremst í `category` í gagnagrunninum.
 * Fyrirtækin sjálf (eigandi, númer, lýsing o.fl.) eru í `companies` með lead_source = "foreldrabok".
 */

/** Hvenær á barnsævinni flokkurinn skiptir mestu máli. */
export type Stig = "Meðganga" | "0–3 mán" | "3–12 mán" | "1–3 ár" | "Allt tímabilið" | "Foreldrarnir";
/** Hve nátengdur flokkurinn er því að eignast barn. */
export type Tenging = "Sterk" | "Miðlungs" | "Veik";
/** Hve stór hluti foreldra þarf þetta. */
export type Eftirspurn = "Allir" | "Margir" | "Sumir";

export interface ForeldrarFlokkur {
  /** Vandamál foreldra, frá sjónarhóli þeirra. */
  vandamal: string;
  stig: Stig;
  /** Sterk = er til vegna barna; Miðlungs = allir nota það en foreldrar þurfa meira eða annað; Veik = almennt heimilishald. */
  tenging: Tenging;
  eftirspurn: Eftirspurn;
  /** Hverjir þjóna flokknum í dag. */
  markadur: string;
  /** Fá fyrirtæki fundust í leitinni; flokkurinn þarf frekari skoðun. */
  fair: boolean;
}

